/* Chart.js loader: attempt to load CDN copy, otherwise provide a no-op fallback.
   This file is intended for production deployments where bundling the
   actual `chart.min.js` can be substituted in place of this loader.
*/
(function(){
  if(typeof window === 'undefined') return;
  // If Chart already present (e.g., vendor file added), do nothing
  if(window.Chart) return;
  // Try to dynamically load official Chart.js from CDN
  var cdn = 'https://cdn.jsdelivr.net/npm/chart.js';
  function loadScript(src, cb){
    var s = document.createElement('script'); s.src = src; s.async = true;
    s.onload = function(){ cb(null); };
    s.onerror = function(){ cb(new Error('failed')); };
    document.head.appendChild(s);
  }
  loadScript(cdn, function(err){
    if(!err && window.Chart) return; // loaded
    // fallback: minimal no-op Chart constructor so UI doesn't break offline
    window.Chart = function(ctx, cfg){ this.ctx = ctx; this.cfg = cfg; this.destroy = function(){}; };
  });
})();
